                    tcol.table_name, tcol.column_name, DECODE(tcol.data_type,''TIMESTAMP(6)'', substr(tcol.data_type,1,INSTR(tcol.data_type,''('')-1),tcol.data_type) data_type, tcol.data_length, tcol.data_precision, tcol.data_scale,
                    ''i'' || decode( tcol.data_type, ''NUMBER'', ''nu'', ''VARCHAR2'', ''sb'', ''DATE'', ''dt'', ''BOOLEAN'', ''bo'', ''CLOB'', ''cl'', ''BLOB'', ''bl'', ''XMLTYPE'', ''xm'',''TIMESTAMP(6)'',''ts'',''INTEGER'',''nu'',''NCHAR'',''sb'' ) || substr( tcol.column_name, 1, 1 ) || lower( substr( tcol.column_name, 2 ) ) alias,
                    ''i'' || decode( tcol.data_type, ''NUMBER'', ''nu'', ''VARCHAR2'', ''sb'', ''DATE'', ''dt'', ''BOOLEAN'', ''bo'', ''CLOB'', ''cl'', ''BLOB'', ''bl'', ''XMLTYPE'', ''xm'',''TIMESTAMP(6)'',''ts'',''INTEGER'',''nu'',''NCHAR'',''sb'' ) || substr( tcol.column_name, 1, 1 ) || lower( substr( tcol.column_name, 2 ) ) || '' '' || ''IN'' || '' '' || lower( tcol.table_name || ''.'' || tcol.column_name) || ''%TYPE''  param_entrada
