                    ''i'' || decode( data_type, ''NUMBER'', ''nu'', ''VARCHAR2'', ''sb'', ''DATE'', ''dt'', ''BOOLEAN'', ''bo'', ''CLOB'', ''cl'', ''BLOB'', ''bl'', ''XMLTYPE'', ''xm'',''TIMESTAMP(6)'',''ts'',''INTEGER'',''nu'',''NCHAR'',''sb'' ) || substr( tcol.column_name, 1, 1 ) || lower( substr( tcol.column_name, 2 ) ) param_alias,
                    ''i'' || decode( data_type, ''NUMBER'', ''nu'', ''VARCHAR2'', ''sb'', ''DATE'', ''dt'', ''BOOLEAN'', ''bo'', ''CLOB'', ''cl'', ''BLOB'', ''bl'', ''XMLTYPE'', ''xm'',''TIMESTAMP(6)'',''ts'',''INTEGER'',''nu'',''NCHAR'',''sb'' ) || substr( tcol.column_name, 1, 1 ) || lower( substr( tcol.column_name, 2 ) ) || '' '' || ''IN'' || '' '' || lower( tcol.table_name || ''.'' || tcol.column_name) || ''%TYPE''  param_entrada
