                            <div class="col">
                                <xsl:value-of select="@autor"/>
                            </div>

                            <div class="col">
                                <xsl:value-of select="@inc"/>
                            </div>

                            <div class="col descripcion">
                                <pre><xsl:value-of select="."/></pre>
                            </div>
                        </div>
                    </xsl:for-each>

                </div>

            </div>

        </div>

    </xsl:for-each>
</div>
</body>
</html>
</xsl:template>
</xsl:stylesheet>'
