                CASE UPPER(isbTipoDato) 
                    WHEN ''NUMBER'' THEN
                        sbToken := sbPrefijo||''nu'';
                    WHEN ''VARCHAR2'' THEN
                        sbToken := sbPrefijo||''sb'';
                    WHEN ''CHAR'' THEN
