                    WHEN ''CLOB'' THEN
                        sbToken := sbPrefijo||''cl'';
                    WHEN ''BLOB'' THEN
                        sbToken := sbPrefijo||''bl'';
                    WHEN ''XMLTYPE'' THEN
                        sbToken := sbPrefijo||''xm'';
                    WHEN ''TIMESTAMP'' THEN
                        sbToken := sbPrefijo||''ts'';  
                    WHEN ''INTEGER'' THEN
                        sbToken := sbPrefijo||''nu'';
                    WHEN ''NCHAR'' THEN
                        sbToken := sbPrefijo||''sb'';
                END CASE;
            END IF;
            RETURN sbToken;   
        END;
        
